import{_ as o,o as s,c as a,a2 as t}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Database store","description":"","frontmatter":{},"headers":[],"relativePath":"repositories/database.md","filePath":"repositories/database.md","lastUpdated":1793547867000}'),n={name:"repositories/database.md"};function c(d,e,r,i,l,p){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="database-store" tabindex="-1">Database store <a class="header-anchor" href="#database-store" aria-label="Permalink to &quot;Database store&quot;">​</a></h1><p><code>@chamvi/store-db</code> (formerly <code>@chamvi/store-typeorm</code>) keeps everything the engine persists in Postgres through TypeORM. It passes <code>describeRepositoryContract</code> unchanged, so the engine behaves the same on memory and on Postgres, also with several replicas on one database.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/store-db</span><span style="color:#E7C58C;"> typeorm</span><span style="color:#E7C58C;"> pg</span></span></code></pre></div><p><code>@chamvi/core</code>, <code>typeorm</code> (<code>^1.1.2</code>) and <code>pg</code> (<code>^8</code>) are peer dependencies.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> dataSource = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> DataSource({</span></span>
<span class="line"><span style="color:#E6DFDE;">    type: </span><span style="color:#E7C58C;">&#39;postgres&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    url: process.env.DATABASE_URL,</span></span>
<span class="line"><span style="color:#E6DFDE;">    entities: STORE_ENTITIES,</span></span>
<span class="line"><span style="color:#E6DFDE;">    migrations: STORE_MIGRATIONS,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> dataSource.initialize();</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> migrateStore(dataSource);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> store = createDatabaseStore({ dataSource });</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [triage],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p><code>createDatabaseStore({ dataSource, clock? })</code> assembles all capabilities, including conversations, over the same <code>DataSource</code>. Each role is a separate class: <code>DatabaseRunRepository</code>, <code>DatabaseStepRepository</code>, <code>DatabaseCheckpointRepository</code>, <code>DatabaseIdempotencyRepository</code>, <code>DatabaseLockRepository</code>, <code>DatabaseEffectRepository</code>, <code>DatabaseStateRepository</code>, <code>DatabaseArtifactRepository</code>, <code>DatabaseAgentRevisionRepository</code> and <code>DatabaseConversationRepository</code>. The repositories take an initialized <code>DataSource</code> and never initialize or destroy it. The database must exist; create it beforehand, for example with <code>createDatabase()</code> from <code>typeorm-extension</code>.</p><p>On shutdown, drain the engine before destroying the data source:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// the store never destroys the data source: the app closes it last</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> shutdown = </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">    clearInterval(purge);</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> engine.drain();</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> dataSource.destroy();</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>dataSource</code></td><td><code>DataSource</code></td><td>required</td><td>An initialized Postgres data source that lists <code>STORE_ENTITIES</code> and <code>STORE_MIGRATIONS</code></td></tr><tr><td><code>clock</code></td><td><code>IClock</code></td><td><code>systemClock</code></td><td>Time source for claims, keys, locks and <code>updatedAt</code></td></tr></tbody></table><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p><code>migrateStore(dataSource)</code> runs the pending migrations under the Postgres advisory lock <code>chamvi:migrations</code> (<code>MIGRATION_LOCK_NAME</code>). Call it on every boot: replicas that start at once wait for each other, and each migration is applied and recorded once. Each call uses one pooled connection, the one holding the lock, for the migrations as well. chamvi is pre-1.0, so a new version may ship a new migration. The migrations so far: <code>1792195200000-init.ts</code>, <code>1792368000000-artifacts.ts</code>, <code>1792454400000-idempotency-scope.ts</code>, <code>1792540800000-kv-key-collation.ts</code> and <code>1792627200000-agent-revisions.ts</code> (<code>AgentRevisions1792627200000</code>, the table <code>chamvi_agent_revisions</code>), followed by <code>1792713600000-conversations-run-taint.ts</code> (<code>ConversationsRunTaint1792713600000</code>: conversation identities, items, notes and operation receipts, run/checkpoint bindings, their foreign keys and indexes on every new foreign key column (including <code>chamvi_conversations.active_run_id</code>), then the nullable <code>chamvi_runs.taint</code> column and the conservative backfill of unfinished runs, see <a href="/repositories/writing-a-repository#persist-run-taint">Persist run taint</a>). Upgrading to it needs downtime: follow <a href="/guide/upgrading#upgrading-to-0-4">Upgrading to 0.4</a>.</p><p>The conversations migration preserves legacy checkpoints and steps whose run does not exist. Earlier store methods allowed those rows, so their run foreign keys are added as PostgreSQL <code>NOT VALID</code>: no rows are deleted and no placeholder runs are created. New inserts and changes to <code>run_id</code> must reference an existing run; the other foreign keys are validated normally. Those two constraints remain unvalidated until the legacy data is reconciled explicitly, and do not need validation for new-write enforcement.</p><h3 id="validating-the-legacy-constraints" tabindex="-1">Validating the legacy constraints <a class="header-anchor" href="#validating-the-legacy-constraints" aria-label="Permalink to &quot;Validating the legacy constraints&quot;">​</a></h3><p>To find the orphans the two <code>NOT VALID</code> constraints tolerate:</p><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">SELECT</span><span style="color:#E7C58C;"> &#39;checkpoint&#39;</span><span style="color:#FF7B84;"> AS</span><span style="color:#E6DFDE;"> kind, </span><span style="color:#E7C58C;">c</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">run_id</span><span style="color:#FF7B84;"> FROM</span><span style="color:#E6DFDE;"> chamvi_checkpoints c</span></span>
<span class="line"><span style="color:#FF7B84;">    WHERE</span><span style="color:#FF7B84;"> NOT</span><span style="color:#FF7B84;"> EXISTS</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">SELECT</span><span style="color:#E7C58C;"> 1</span><span style="color:#FF7B84;"> FROM</span><span style="color:#E6DFDE;"> chamvi_runs r </span><span style="color:#FF7B84;">WHERE</span><span style="color:#E7C58C;"> r</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">id</span><span style="color:#E6DFDE;"> = </span><span style="color:#E7C58C;">c</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">run_id</span><span style="color:#E6DFDE;">)</span></span>
<span class="line"><span style="color:#FF7B84;">UNION ALL</span></span>
<span class="line"><span style="color:#FF7B84;">SELECT</span><span style="color:#E7C58C;"> &#39;step&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">s</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">run_id</span><span style="color:#FF7B84;"> FROM</span><span style="color:#E6DFDE;"> chamvi_steps s</span></span>
<span class="line"><span style="color:#FF7B84;">    WHERE</span><span style="color:#FF7B84;"> NOT</span><span style="color:#FF7B84;"> EXISTS</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">SELECT</span><span style="color:#E7C58C;"> 1</span><span style="color:#FF7B84;"> FROM</span><span style="color:#E6DFDE;"> chamvi_runs r </span><span style="color:#FF7B84;">WHERE</span><span style="color:#E7C58C;"> r</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">id</span><span style="color:#E6DFDE;"> = </span><span style="color:#E7C58C;">s</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">run_id</span><span style="color:#E6DFDE;">);</span></span></code></pre></div><p>Orphans are leftovers no run can resume. Once you have kept what you need (a backup, an audit export) and deleted them, validate the constraints; <code>VALIDATE CONSTRAINT</code> takes only a <code>SHARE UPDATE EXCLUSIVE</code> lock, so writes continue meanwhile:</p><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">DELETE</span><span style="color:#FF7B84;"> FROM</span><span style="color:#E6DFDE;"> chamvi_checkpoints c </span><span style="color:#FF7B84;">WHERE</span><span style="color:#FF7B84;"> NOT</span><span style="color:#FF7B84;"> EXISTS</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">SELECT</span><span style="color:#E7C58C;"> 1</span><span style="color:#FF7B84;"> FROM</span><span style="color:#E6DFDE;"> chamvi_runs r </span><span style="color:#FF7B84;">WHERE</span><span style="color:#E7C58C;"> r</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">id</span><span style="color:#E6DFDE;"> = </span><span style="color:#E7C58C;">c</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">run_id</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#FF7B84;">DELETE</span><span style="color:#FF7B84;"> FROM</span><span style="color:#E6DFDE;"> chamvi_steps s </span><span style="color:#FF7B84;">WHERE</span><span style="color:#FF7B84;"> NOT</span><span style="color:#FF7B84;"> EXISTS</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">SELECT</span><span style="color:#E7C58C;"> 1</span><span style="color:#FF7B84;"> FROM</span><span style="color:#E6DFDE;"> chamvi_runs r </span><span style="color:#FF7B84;">WHERE</span><span style="color:#E7C58C;"> r</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">id</span><span style="color:#E6DFDE;"> = </span><span style="color:#E7C58C;">s</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">run_id</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#FF7B84;">ALTER</span><span style="color:#FF7B84;"> TABLE</span><span style="color:#E6DFDE;"> chamvi_checkpoints VALIDATE </span><span style="color:#FF7B84;">CONSTRAINT</span><span style="color:#E7C58C;"> &quot;FK_4aac9035497a94deb8cdb39062e&quot;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">ALTER</span><span style="color:#FF7B84;"> TABLE</span><span style="color:#E6DFDE;"> chamvi_steps VALIDATE </span><span style="color:#FF7B84;">CONSTRAINT</span><span style="color:#E7C58C;"> &quot;FK_ec83b59c000dc26e022836e98b7&quot;</span><span style="color:#E6DFDE;">;</span></span></code></pre></div><p>chamvi never runs these itself; a validated constraint changes nothing for the engine.</p><p><code>pendingMigrations(dataSource)</code> resolves the names of the migrations not run yet, in order, without writing anything (it never creates TypeORM&#39;s <code>migrations</code> table); <code>chamvi start --check</code> uses it to refuse a database a start with <code>CHAMVI_MIGRATE=false</code> could not run on (with the default <code>true</code> a start migrates, so the check passes).</p><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Holds</th><th>Keys and indexes</th></tr></thead><tbody><tr><td><code>chamvi_runs</code></td><td>Runs; JSON columns for trigger, output, error, usage, wait point and <code>taint</code>; the run&#39;s <code>address</code> in the <code>thread</code> column; claim owner and expiry; the conversation binding</td><td>PK <code>id</code> (<code>COLLATE &quot;C&quot;</code>); <code>(agent, status, concurrency_key)</code>; <code>(status, created_at, id)</code>; <code>conversation_scope_id</code></td></tr><tr><td><code>chamvi_steps</code></td><td>Append-only steps</td><td><code>(run_id, step_index)</code></td></tr><tr><td><code>chamvi_checkpoints</code></td><td>The latest checkpoint per run</td><td>PK <code>run_id</code>; <code>conversation_scope_id</code></td></tr><tr><td><code>chamvi_conversations</code></td><td>Conversation identities, generation, active owner and its snapshot</td><td>PK <code>id</code> (<code>COLLATE &quot;C&quot;</code>)</td></tr><tr><td><code>chamvi_conversation_items</code></td><td>Transcript items and the send journal</td><td>PK <code>seq</code>; unique <code>(scope_id, generation, id)</code>; <code>(scope_id, generation, created_at, seq)</code>; <code>run_id</code></td></tr><tr><td><code>chamvi_conversation_notes</code></td><td>Explicit notes</td><td>PK <code>(scope_id, generation, key)</code>; <code>expires_at</code>; <code>run_id</code></td></tr><tr><td><code>chamvi_conversation_operations</code></td><td>Note operation receipts</td><td>PK <code>(scope_id, generation, id)</code>; <code>(scope_id, created_at, id)</code>; <code>run_id</code></td></tr><tr><td><code>chamvi_idempotency_keys</code></td><td>Intake keys</td><td>PK <code>(scope, key)</code>; <code>expires_at</code></td></tr><tr><td><code>chamvi_locks</code></td><td>Keyed leases</td><td>PK <code>key</code>; <code>expires_at</code></td></tr><tr><td><code>chamvi_effects</code></td><td>Recorded effect results</td><td>PK <code>key</code></td></tr><tr><td><code>chamvi_kv</code></td><td>Agent key-value state</td><td>PK <code>(agent, key)</code>, <code>key</code> <code>COLLATE &quot;C&quot;</code> (migration <code>1792540800000-kv-key-collation.ts</code>)</td></tr><tr><td><code>chamvi_docs</code></td><td>Agent document collections</td><td>PK <code>(agent, collection, id)</code>; GIN index on <code>doc</code></td></tr><tr><td><code>chamvi_artifacts</code></td><td>Artifact metadata and bytes (<code>data</code> <code>bytea</code>)</td><td>PK <code>id</code>; <code>run_id</code></td></tr><tr><td><code>chamvi_agent_revisions</code></td><td>One revision marker per folder agent: <code>hash</code> varchar(128), <code>changed_at</code></td><td>PK <code>agent</code> varchar(64) <code>COLLATE &quot;C&quot;</code> (migration <code>1792627200000-agent-revisions.ts</code>)</td></tr></tbody></table><p>Conversation rows, active owners, transcript items, notes and operation receipts use foreign keys to their local runs and identities. Steps and checkpoints also require an existing run. Use the same DataSource for every built-in TypeORM role; these relationships do not create a transaction spanning run dispatch, conversation mutation and generic effects. See <a href="/guide/conversations">Conversation memory</a>.</p><h2 id="how-it-keeps-the-contract" tabindex="-1">How it keeps the contract <a class="header-anchor" href="#how-it-keeps-the-contract" aria-label="Permalink to &quot;How it keeps the contract&quot;">​</a></h2><ul><li><strong>Repositories and query builders.</strong> Every method goes through the entities&#39; TypeORM repositories, find options and query builders. Hand-written fragments remain only where find options cannot express the condition: the <code>jsonb_exists</code> key check in <code>findDocuments</code> (TypeORM has no key-existence operator) and the UTF-8 byte-length bound of conversation recall (<code>octet_length</code>).</li><li><strong>One statement for each listed atomic operation</strong>, never read-then-write in JavaScript: <ul><li><code>runs.insert</code>: an insert with <code>orIgnore()</code> (<code>ON CONFLICT DO NOTHING RETURNING id</code>).</li><li><code>idempotency.claim</code> and <code>locks.acquire</code>: an insert with <code>orUpdate()</code> and an overwrite condition (<code>ON CONFLICT DO UPDATE ... WHERE expires_at &lt;= now RETURNING</code>), so an expired key or lock is taken over in the same statement.</li><li><code>runs.claim</code> and <code>runs.renewClaim</code>: a conditional update (<code>UPDATE ... WHERE ...</code>) checked by its affected-row count.</li><li>The <code>runs.update</code> guards: a conditional update with <code>RETURNING *</code>; when it matches no row, the store reads the run to throw <code>RunNotFoundError</code> or <code>InvalidRunStateError</code>.</li><li><code>checkpoints.save</code>: an insert with <code>orUpdate()</code> and the overwrite condition <code>step_index &lt;=</code> the new index.</li><li><code>artifacts.insert</code>: an insert with <code>orIgnore()</code> returning <code>id</code>.</li><li><code>agentRevisions.save</code>: an upsert on <code>agent</code>. The marker needs no atomic compare: the engine reads and writes it under the store lock <code>agents:&lt;name&gt;</code>.</li></ul></li><li><strong>Conversation transactions.</strong> Conversation ownership and journal changes use transactions and a <code>FOR NO KEY UPDATE</code> lock on the conversation row rather than the single-statement pattern above (the row is never deleted and its key never changes, so the lock does not block the <code>KEY SHARE</code> locks of child-row foreign key checks).</li><li><strong>Missing runs.</strong> A step, checkpoint or conversation turn of a run that does not exist fails the foreign key; the store reports it as <code>RunNotFoundError</code>, like <code>createMemoryStore()</code>.</li><li><strong>Time from the clock.</strong> The injected <code>IClock</code>&#39;s time is passed as a parameter; queries never call the database&#39;s <code>now()</code>.</li><li><strong>No aliasing.</strong> Values are serialized into the query and parsed out again; nothing is cached in memory.</li><li><strong>Dates.</strong> Timestamps are <code>timestamptz</code>; <code>trigger.receivedAt</code>, <code>trigger.attachments[].createdAt</code>, <code>waiting.expiresAt</code>, <code>waiting.notifiedAt</code> and <code>taint.at</code> live in JSON and are revived as <code>Date</code>.</li></ul><h2 id="housekeeping" tabindex="-1">Housekeeping <a class="header-anchor" href="#housekeeping" aria-label="Permalink to &quot;Housekeeping&quot;">​</a></h2><p>Expired idempotency keys and locks never block anyone, but they stay in their tables until purged:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// expired keys and locks stay until purged: purge every hour</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> purge = setInterval(() </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">    Promise.all([store.idempotency.purgeExpired(), store.locks.purgeExpired()])</span></span>
<span class="line"><span style="color:#E6DFDE;">        .catch((e: unknown) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> console.error(e));</span></span>
<span class="line"><span style="color:#E6DFDE;">}, </span><span style="color:#E7C58C;">60</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">60</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">1000</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6DFDE;">purge.unref();</span></span></code></pre></div><p><code>store.idempotency.purgeExpired(now?)</code> and <code>store.locks.purgeExpired(now?)</code> each delete their expired rows and return the number removed. The default time comes from the clock. Effects have no expiry and are never purged. Direct engine users schedule both as above; the app&#39;s built-in store module schedules them with <code>CHAMVI_PURGE_INTERVAL_MS</code>.</p><h2 id="differences-from-memory-repositories" tabindex="-1">Differences from memory repositories <a class="header-anchor" href="#differences-from-memory-repositories" aria-label="Permalink to &quot;Differences from memory repositories&quot;">​</a></h2><ul><li><strong>Opaque values are JSON.</strong> A run&#39;s <code>output</code>, step <code>input</code>/<code>output</code>/<code>error</code>, checkpoint messages, effect results and state lose <code>Date</code>, <code>undefined</code> and <code>Map</code> fidelity, and a typed array such as <code>Uint8Array</code> comes back as an object keyed by index. A <code>BigInt</code> or a circular structure makes the write throw a <code>TypeError</code>.</li><li><strong>NUL characters and lone surrogates become U+FFFD</strong> in opaque values, keys and strings alike, because <code>jsonb</code> cannot hold them.</li><li><strong>Artifact bytes are <code>bytea</code></strong>, never selected by <code>findOne</code> or <code>find</code>, and come back from <code>read</code> as a plain <code>Uint8Array</code>. Postgres caps a <code>bytea</code> value at 1 GB and the whole value travels in one query, so keep artifacts small enough for memory. Nothing purges artifacts yet.</li><li><strong>Identifiers have length limits</strong> (<code>createMemoryStore()</code> has none): run and artifact ids 128 characters; <code>concurrencyKey</code>, <code>address</code>, claim owners, step names, document collections and document ids 255; idempotency, lock, effect and state keys 512; idempotency scopes 1024 (<code>&lt;agent&gt;:&lt;source&gt;:&lt;kind&gt;:&lt;id&gt;</code> with the invoker URI-encoded, leaving about 950 characters for the encoded <code>kind</code> and <code>id</code>). A longer value makes the write fail with the driver&#39;s <code>value too long</code> error, so validate user-supplied keys before they reach <code>dispatch</code> (a rejected run with an <code>idempotencyKey</code> keeps its key reserved until the key expires).</li><li><strong><code>null</code> in an optional property reads back as absent:</strong> a run <code>output</code> of <code>null</code>, and a step <code>input</code>, <code>output</code> or <code>error</code> of <code>null</code>, are stored as SQL <code>NULL</code>. <code>effects.save(key, undefined)</code> reads back <code>{ result: null }</code> and <code>upsertDocument(..., undefined)</code> reads back <code>doc: null</code>.</li><li><strong><code>findDocuments</code> <code>where</code> uses <code>jsonb</code> containment (<code>@&gt;</code>).</strong> Primitive values match by top-level equality; a nested object or array matches by containment, where <code>createMemoryStore()</code> never matches. A key whose value is <code>undefined</code> matches documents that lack the key, as in <code>createMemoryStore()</code>. Documents come back ordered by <code>id</code>, not by insertion.</li><li><strong><code>runs.find</code> ties</strong> on <code>createdAt</code> are broken by the byte order of <code>id</code> (<code>COLLATE &quot;C&quot;</code>, so <code>&#39;B&#39; &lt; &#39;a&#39;</code>, reversed for <code>order: &#39;desc&#39;</code>); identical to <code>createMemoryStore()</code> for lowercase ids and UUIDs.</li></ul>`,31)])])}const u=o(n,[["render",c]]);export{y as __pageData,u as default};
